static void sctp_sock_migrate(struct sock *oldsk, struct sock *newsk, struct sctp_association *assoc, sctp_socket_type_t type) {
    struct sctp_sock *oldsp = sctp_sk(oldsk);
    struct sctp_sock *newsp = sctp_sk(newsk);
    struct sctp_bind_bucket *pp; /* hash list port iterator */
    struct sctp_endpoint *newep = newsp->ep;
    struct sk_buff *skb, *tmp;
    struct sctp_ulpevent *event;
    int flags = 0;

    /* Migrate socket buffer sizes and all the socket level options to the new socket. */
    newsk->sk_sndbuf = oldsk->sk_sndbuf;
    newsk->sk_rcvbuf = oldsk->sk_rcvbuf;

    /* Brute force copy old sctp opt. */
    inet_sk_copy_descendant(newsk, oldsk);

    /* Restore the ep value that was overwritten with the above structure copy. */
    newsp->ep = newep;
    newsp->hmac = NULL;

    /* Hook this new socket in to the bind_hash list. */
    pp = sctp_sk(oldsk)->bind_hash;
    sk_add_bind_node(newsk, &pp->owner);
    sctp_sk(newsk)->bind_hash = pp;
    inet_sk(newsk)->num = inet_sk(oldsk)->num;

    /* Copy the bind_addr list from the original endpoint to the new endpoint so that we can handle restarts properly */
    if (PF_INET6 == assoc->base.sk->sk_family)
        flags = SCTP_ADDR6_ALLOWED;
    if (assoc->peer.ipv4_address)
        flags |= SCTP_ADDR4_PEERSUPP;
    if (assoc->peer.ipv6_address)
        flags |= SCTP_ADDR6_PEERSUPP;
    sctp_bind_addr_copy(&newsp->ep->base.bind_addr, &oldsp->ep->base.bind_addr, SCTP_SCOPE_GLOBAL, GFP_KERNEL, flags);

    /* Move any messages in the old socket's receive queue that are for the peeled off association to the new socket's receive queue. */
    sctp_skb_for_each(skb, &oldsk->sk_receive_queue, tmp) {
        event = sctp_skb2event(skb);
        if (event->asoc == assoc) {
            sctp_sock_rfree_frag(skb);
            __skb_unlink(skb, &oldsk->sk_receive_queue);
            __skb_queue_tail(&newsk->sk_receive_queue, skb);
            sctp_skb_set_owner_r_frag(skb, newsk);
        }
    }

    /* Clean up any messages pending delivery due to partial delivery. */
    skb_queue_head_init(&newsp->pd_lobby);
    sctp_sk(newsk)->pd_mode = assoc->ulpq.pd_mode;
    if (sctp_sk(oldsk)->pd_mode) {
        struct sk_buff_head *queue;
        /* Decide which queue to move pd_lobby skbs to. */
        if (assoc->ulpq.pd_mode) {
            queue = &newsp->pd_lobby;
        } else
            queue = &newsk->sk_receive_queue;
        /* Walk through the pd_lobby, looking for skbs that need moved to the new socket. */
        sctp_skb_for_each(skb, &oldsp->pd_lobby, tmp) {
            event = sctp_skb2event(skb);
            if (event->asoc == assoc) {
                sctp_sock_rfree_frag(skb);
                __skb_unlink(skb, &oldsp->pd_lobby);
                __skb_queue_tail(queue, skb);
                sctp_skb_set_owner_r_frag(skb, newsk);
            }
        }
        /* Clear up any skbs waiting for the partial delivery to finish. */
        if (assoc->ulpq.pd_mode)
            sctp_clear_pd(oldsk);
    }

    sctp_skb_for_each(skb, &assoc->ulpq.reasm, tmp) {
        sctp_sock_rfree_frag(skb);
        sctp_skb_set_owner_r_frag(skb, newsk);
    }

    sctp_skb_for_each(skb, &assoc->ulpq.lobby, tmp) {
        sctp_sock_rfree_frag(skb);
        sctp_skb_set_owner_r_frag(skb, newsk);
    }

    /* Set the type of socket to indicate that it is peeled off from the original UDP-style socket or created with the accept() call on a TCP-style socket. */
    newsp->type = type;

    /* Mark the new socket "in-use" by the user so that any packets that may arrive on the association after we've moved it are queued to the backlog. This prevents a potential race between backlog processing on the old socket and new-packet processing on the new socket. */
    sctp_lock_sock(newsk);
    sctp_assoc_migrate(assoc, newsk);

    /* If the association on the newsk is already closed before accept() is called, set RCV_SHUTDOWN flag. */
    if (sctp_state(assoc, CLOSED) && sctp_style(newsk, TCP))
        newsk->sk_shutdown |= RCV_SHUTDOWN;

    newsk->sk_state = SCTP_SS_ESTABLISHED;

    sctp_release_sock(newsk);
}
